package tr.gov.kocaeli.sehir.approval.api;
import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import tr.gov.kocaeli.sehir.approval.application.ApprovalService;import java.util.*;
@RestController @RequestMapping("/api/v1/approvals")public class ApprovalController{private final ApprovalService service;public ApprovalController(ApprovalService service){this.service=service;}@PostMapping@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','UNIT_MANAGER','TECHNICAL_REVIEWER')")Map<String,Object>submit(@RequestBody ApprovalService.Submit body){return service.submit(body);}@PostMapping("/{id}/decision")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','APPROVER')")Map<String,Object>decide(@PathVariable UUID id,@RequestBody ApprovalService.Decision body){return service.decide(id,body);}@GetMapping("/{id}")Map<String,Object>get(@PathVariable UUID id){return service.get(id);}}
